export type Look = { color: string; outfit: string; hat: string };
export const hatSvg = (name: string) => { const h = HATS[name] ?? ""; return typeof h === "string" ? char(h) : h.raw; };
export const outfitSvg = (name: string) => char(OUTFITS[name] ?? "");
export const bodySvg = (color: string) => char(body(BODY_COLORS[color] ?? BODY_COLORS.Pink));
function char(inner: string) { return `<svg viewBox="0 -40 200 340" fill="none" overflow="visible" xmlns="http://www.w3.org/2000/svg">${inner}</svg>`; }
